        case 4: h.remove(id, child: r.u32())
        case 5: let prop = r.u16(); h.setProp(id, prop: prop, value: r.value(r.u8()))
        case 6: h.setFrame(id, x: r.f32(), y: r.f32(), width: r.f32(), height: r.f32())
        case 7: h.listen(id, event: r.u16())
        case 8: h.unlisten(id, event: r.u16())
        case 9: let cmd = r.u16(); h.command(id, command: cmd, args: r.bytes())
        case 10: h.setRoot(id)
        default: fatalError("nui: bad op code \(code)")
        }
    }
}

